-- Dados fake para testes manuais via Swagger.
-- Os IDs são fixos e usados nos exemplos (@Schema/@Parameter) da API.
-- Só é executado no profile "local" (ver application-local.properties).
-- Migration repetível: roda de novo quando o arquivo muda, por isso os
-- inserts usam ON CONFLICT DO NOTHING.
--
-- Login: use GET /api/autenticacao/gera-token-atendente ou gera-token-mecanico
-- (funcionários criados na V17).

-- Clientes (CPF/CNPJ com dígitos verificadores válidos)
ON CONFLICT DO NOTHING;

-- Veículos (placas no padrão antigo e Mercosul). O 7 não tem OS: use-o para testar o DELETE.
ON CONFLICT DO NOTHING;

-- Serviços. O 6 não está em orçamento: use-o para testar o DELETE.
ON CONFLICT DO NOTHING;

-- Insumos. O 6 não tem estoque nem orçamento: use-o para testar o DELETE.
ON CONFLICT DO NOTHING;

-- Estoque (insumo usado em orçamento precisa de registro, senão a aprovação falha; vela de ignição zerada para simular falta de peça)
ON CONFLICT DO NOTHING;

-- Ordens de serviço: uma pronta para cada endpoint do fluxo.
-- Número público + código de acesso (o banco guarda o SHA-256 do código):
--   55555555-5555-5555-5555-000000000001  OS-2026-900001  código ABCD2345  -> iniciar-diagnostico
--   55555555-5555-5555-5555-000000000002  OS-2026-900002  código EFGH6789  -> orcamento: adicionar-insumos / adicionar-servicos / finalizar
--   55555555-5555-5555-5555-000000000003  OS-2026-900003  código JKLM2345  -> aprovar (cliente João, código JKLM2345)
--   55555555-5555-5555-5555-000000000004  OS-2026-900004  código NPQR6789  -> reprovar (cliente Carlos, código NPQR6789)
--   55555555-5555-5555-5555-000000000005  OS-2026-900005  código STUV2345  -> aprovar sem estoque -> AGUARDANDO_PECAS (cliente Maria, código STUV2345)
--   55555555-5555-5555-5555-000000000006  OS-2026-900006  código WXYZ6789  -> iniciar-servico
--   55555555-5555-5555-5555-000000000007  OS-2026-900007  código ABCD6789  -> finalizar-servico
--   55555555-5555-5555-5555-000000000008  OS-2026-900008  código EFGH2345  -> registrar-pagamento
--   55555555-5555-5555-5555-000000000009  OS-2026-900009  código JKLM6789  -> entregar-veiculo
--   55555555-5555-5555-5555-000000000010  OS-2026-900010  código NPQR2345  -> ENTREGUE (tempo-medio-execucao)
--   55555555-5555-5555-5555-000000000011  OS-2026-900011  código STUV6789  -> ENTREGUE (tempo-medio-execucao)
ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

